// Pure helpers for the 2-step Steam link flow (docs/REVIEW_FIXES.md §1). No React / Expo imports,
// so they can be unit-tested directly.

/** What the Steam redirect (gg://steam-linked?steam=…) told us. */
export type SteamReturn =
  | { kind: 'verified'; code: string }
  | { kind: 'linked' } // older server versions linked directly
  | { kind: 'cancel' }
  | { kind: 'error'; reason: string }
  | { kind: 'none' };

/** The completion code is a uuid generated by the server. */
const CODE_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

function first(v: unknown): string {
  if (Array.isArray(v)) return typeof v[0] === 'string' ? v[0] : '';
  return typeof v === 'string' ? v : '';
}

/** Reads `steam`, `code` and `reason` from route / URL query params. */
export function readSteamParams(params: Record<string, unknown> | null | undefined): SteamReturn {
  const steam = first(params?.steam);
  if (steam === 'verified') {
    const code = first(params?.code).trim();
    return CODE_RE.test(code) ? { kind: 'verified', code: code.toLowerCase() } : { kind: 'error', reason: 'invalid' };
  }
  if (steam === 'linked') return { kind: 'linked' };
  if (steam === 'cancel') return { kind: 'cancel' };
  if (steam === 'error') return { kind: 'error', reason: first(params?.reason) };
  return { kind: 'none' };
}

/**
 * Runs `fn` at most once per key; later callers with the same key get the same promise.
 * Used so a completion code is never sent twice (browser result + deep link route).
 */
export function createOnce<T>(): (key: string, fn: () => Promise<T>) => Promise<T> {
  const seen = new Map<string, Promise<T>>();
  return (key, fn) => {
    const existing = seen.get(key);
    if (existing) return existing;
    const p = fn();
    seen.set(key, p);
    return p;
  };
}

/**
 * One outcome message per link attempt. Both the in-app browser result and the
 * /steam-linked route may finish the same attempt; only the first one to claim it shows a message.
 */
export function createAttemptClaim() {
  let attempt = 0;
  let claimed = -1;
  return {
    /** Call when a new "Sign in through Steam" starts. */
    begin(): void {
      attempt += 1;
    },
    /** True for the first caller of the current attempt, false afterwards. */
    claim(): boolean {
      if (claimed === attempt) return false;
      claimed = attempt;
      return true;
    },
  };
}

/** "Try again in 3 minutes." from the server's retry_after_seconds. */
export function minutesLeft(retryAfterSeconds: unknown): number {
  const s = typeof retryAfterSeconds === 'number' && Number.isFinite(retryAfterSeconds) ? retryAfterSeconds : 300;
  return Math.max(1, Math.ceil(s / 60));
}
